import {snowShore} from './aurora-terrain.js';
export function snowWalkable(x,z){const r=Math.hypot(x,z);return r<9.7&&Math.asin(Math.min(1,r/10))<snowShore(Math.atan2(z,x))-.025;}
export function clearOf(x,z,circles,r=.24){return circles.every(c=>Math.hypot(x-c.x,z-c.z)>=c.radius+r);}
export function separatePoint(x,z,circles,r=.24){for(let pass=0;pass<8;pass++){let hit=false;for(const c of circles){let dx=x-c.x,dz=z-c.z,d=Math.hypot(dx,dz),gap=c.radius+r+.015;if(d<gap){if(d<1e-6){dx=1;dz=0;d=1;}x=c.x+dx/d*gap;z=c.z+dz/d*gap;hit=true;}}if(!hit)break;}return {x,z};}
export function snowRoute(from,to,circles,r=.24){const step=.25,W=81,pos=k=>({x:(k%W-40)*step,z:(Math.floor(k/W)-40)*step}),valid=k=>{const p=pos(k);return snowWalkable(p.x,p.z)&&clearOf(p.x,p.z,circles,r)},nearest=p=>{let best=-1,d=Infinity;for(let k=0;k<W*W;k++){const q=pos(k),dist=(q.x-p.x)**2+(q.z-p.z)**2;if(dist<d&&valid(k)){best=k;d=dist;}}return best};if(!snowWalkable(to.x,to.z)||!clearOf(to.x,to.z,circles,r))return [];const a=nearest(from),b=nearest(to);if(a<0||b<0)return [];const queue=[a],prev=new Map([[a,-1]]);for(let i=0;i<queue.length;i++){const k=queue[i];if(k===b){const path=[];for(let n=b;n!==a;n=prev.get(n))path.push(pos(n));path.reverse();path.push(to);return path;}for(const [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=k%W+dx,z=Math.floor(k/W)+dz,n=z*W+x;if(x<0||x>=W||z<0||z>=W||prev.has(n)||!valid(n))continue;prev.set(n,k);queue.push(n);}}return [];}
